import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, SendMessageParams, UsageMetadata} from '../types/ai.js';
import {AIError} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';
import type {ToolResponse} from './tools/registry.js';
import type {OutgoingMessage} from '../types/messages.js';
import type {SessionEntry} from '../types/session.js';

// Fixed: nothing asserts on it, and new Date() would tie the run to the clock.
const SENT_AT = '2026-01-01T00:00:00.000Z';

// One expect per test needs the rejection as a value rather than a matcher.
const outcomeOf = (call: Promise<unknown>): Promise<string> =>
  call.then(() => 'resolved without throwing').catch((error: Error) => error.message);

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

function createMockProvider(response: string, usage?: UsageMetadata): AIProvider {
  return {
    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
      yield {type: 'text', text: response};
      yield {type: 'stop', stopReason: 'end_turn', usage};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

function createErrorProvider(error: Error): AIProvider {
  return {
    // eslint-disable-next-line require-yield
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw error;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

type RecordedHook =
  | 'beforeSession'
  | 'beforeUserInput'
  | 'afterUserInput'
  | 'beforeModelResponse'
  | 'afterModelResponse'
  | 'afterSession'
  | 'onError';
    },
  };
};

describe('ChatOrchestrator hooks', () => {
  describe('beforeSession', () => {
    it('called before anything else', async () => {
      const callOrder: string[] = [];
      const hooks = recordingHooks(callOrder, ['beforeSession', 'beforeUserInput', 'beforeModelResponse']);

      const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});
      await orchestrator.processMessage(createSession('hello'));

      expect(callOrder[0]).toBe('beforeSession');
    });

    it('hands onError the error beforeSession threw', async () => {
      const thrown = new Error('allocation failed');
      let received: Error | undefined;
      const hooks: OrchestratorHooks = {
        beforeSession: async () => {
          throw thrown;
        },
        onError: async (_session, error) => {
          received = error;
        },
      };

      const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});
      await outcomeOf(orchestrator.processMessage(createSession('hello')));

      expect(received).toBe(thrown);
    });
  });

  describe('afterSession', () => {
    it('called after everything completes', async () => {
      const callOrder: string[] = [];
      const hooks = recordingHooks(callOrder, ['afterModelResponse', 'afterSession']);

      const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});
      await orchestrator.processMessage(createSession('hello'));

      expect(callOrder).toEqual(['afterModelResponse', 'afterSession']);
    });

    it('called even when an error occurs', async () => {
      let afterSessionCalled = false;
      const hooks: OrchestratorHooks = {
        onError: async () => {},
        afterSession: async () => {
          afterSessionCalled = true;
        },
      };

      const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
        hooks,
      });
      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));

      expect({outcome, afterSessionCalled}).toEqual({outcome: 'boom', afterSessionCalled: true});
}
```

The hooks fire in this order:

```
beforeSession → beforeUserInput → afterUserInput → beforeModelResponse → ...streaming (beforeToolCall × each tool call, each round)... → onToolBudgetExhausted (only on an exhausted budget) → afterModelResponse → afterSession
```

- The order above holds for a successful pass ([validated by: calls all hooks in correct order](../../src/orchestration/chatOrchestrator.test.ts#L304)).
- When the stream fails, `afterModelResponse` is skipped and the tail becomes `onError` then `afterSession` ([validated by: error path calls onError then afterSession](../../src/orchestration/chatOrchestrator.test.ts#L344)).
- `beforeSession` runs before any other hook ([validated by: called before anything else](../../src/orchestration/chatOrchestrator.test.ts#L106)).
- A throw from `beforeSession` reaches `onError` like any other failure in the turn ([validated by: hands onError the error beforeSession threw](../../src/orchestration/chatOrchestrator.test.ts#L116)).
- `beforeUserInput` receives the content of the last user message ([validated by: receives the last user message content](../../src/orchestration/chatOrchestrator.test.ts#L165)).
- `beforeUserInput` can modify that message by returning a different string ([validated by: modifies user message when returning different value](../../src/orchestration/chatOrchestrator.test.ts#L180)).
- `afterUserInput` receives the message as `beforeUserInput` left it, not as the client sent it ([validated by: receives user message after any beforeUserInput modification](../../src/orchestration/chatOrchestrator.test.ts#L195)).
- `beforeModelResponse` can replace the system prompt, for example loading it from a `PromptStore` ([validated by: replaces system prompt with returned value](../../src/orchestration/chatOrchestrator.test.ts#L212)).
- `afterModelResponse` receives the collected response text and the usage the provider reported ([validated by: receives collected response text and usage](../../src/orchestration/chatOrchestrator.test.ts#L227)).
- `afterModelResponse` does not run when the stream throws, so it never reports a response that was not delivered ([validated by: not called when stream throws](../../src/orchestration/chatOrchestrator.test.ts#L247)).
- `onError` receives the session and the error ([validated by: called with session and error when stream fails](../../src/orchestration/chatOrchestrator.test.ts#L269)).
- `onError` observes rather than handles: the error still propagates to the caller after it returns ([validated by: error still propagates after onError hook](../../src/orchestration/chatOrchestrator.test.ts#L291)).

